import { marked } from "marked";

export type Book = {
  slug: string;
  title: string;
  author: string;
  year: number;
  rating: number;
  tags: string[];
};

const files = import.meta.glob("/content/books/*.md", {
  query: "?raw",
  import: "default",
  eager: true,
}) as Record<string, string>;

function parseList(v: string): string[] {
  const inner = v.trim().replace(/^\[/, "").replace(/\]$/, "");
  return inner
    .split(",")
    .map(s => s.trim().replace(/^["']|["']$/g, ""))
    .filter(Boolean);
}

function parse(path: string, raw: string): Book & { body: string } {
  const slug = path.replace(/^.*\//, "").replace(/\.md$/, "");
  const m = raw.replace(/\r\n/g, "\n").match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  const data: Record<string, string> = {};
  for (const line of (m?.[1] ?? "").split("\n")) {
    const i = line.indexOf(":");
    if (i > 0) data[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  const unquote = (s = "") => s.replace(/^["']|["']$/g, "");
  return {
    slug,
    title: unquote(data.title),
    author: unquote(data.author),
    year: Number(data.year),
    rating: Number(data.rating),
    tags: parseList(data.tags ?? ""),
    body: m?.[2] ?? "",
  };
}

const all = Object.entries(files).map(([p, r]) => parse(p, r));

const byTitle = (a: Book, b: Book) => (a.title < b.title ? -1 : a.title > b.title ? 1 : 0);

export function listBooks(): Book[] {
  return all.map(({ body, ...b }) => b).sort(byTitle);
}

export function topBooks(): Book[] {
  return listBooks()
    .sort((a, b) => b.rating - a.rating || byTitle(a, b))
    .slice(0, 3);
}

export function getBook(slug: string): (Book & { html: string }) | null {
  const b = all.find(x => x.slug === slug);
  if (!b) return null;
  const { body, ...rest } = b;
  return { ...rest, html: marked.parse(body, { async: false }) as string };
}
