import { createSignal, onMount } from "solid-js";

const KEY = "bookshelf:favorites";
const [favs, setFavs] = createSignal<string[]>([]);
let loaded = false;

export function useFavorites() {
  onMount(() => {
    if (loaded) return;
    loaded = true;
    try {
      const v = JSON.parse(localStorage.getItem(KEY) ?? "[]");
      if (Array.isArray(v)) setFavs(v);
    } catch {}
  });
  return {
    has: (slug: string) => favs().includes(slug),
    toggle(slug: string) {
      const next = favs().includes(slug) ? favs().filter(s => s !== slug) : [...favs(), slug];
      setFavs(next);
      localStorage.setItem(KEY, JSON.stringify(next));
    },
  };
}
