import { Title } from "@solidjs/meta";
import { action, useSubmission } from "@solidjs/router";
import { createSignal, Show } from "solid-js";

type Values = { name: string; email: string; message: string };
type Errors = { name?: string; email?: string; message?: string };

function validate(v: Values): Errors {
  const e: Errors = {};
  if (!v.name) e.name = "Name is required.";
  if (!v.email) e.email = "Email is required.";
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email)) e.email = "Enter a valid email address.";
  if (v.message.length < 20) e.message = "Message must be at least 20 characters.";
  return e;
}

function read(form: FormData): Values {
  const g = (k: string) => String(form.get(k) ?? "").trim();
  return { name: g("name"), email: g("email"), message: g("message") };
}

const send = action(async (form: FormData) => {
  "use server";
  const values = read(form);
  const errors = validate(values);
  return { values, errors, ok: Object.keys(errors).length === 0 };
}, "contact");

export default function Contact() {
  const sub = useSubmission(send);
  const [clientErrors, setClientErrors] = createSignal<Errors | null>(null);
  const errors = () => clientErrors() ?? sub.result?.errors ?? {};
  const values = () => sub.result?.values;
  const ok = () => clientErrors() === null && sub.result?.ok === true;

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={ok()}>
        <p>Thanks, {values()!.name}! Your message has been sent.</p>
      </Show>
      <form
        action={send}
        method="post"
        novalidate
        on:submit={e => {
          const errs = validate(read(new FormData(e.currentTarget)));
          if (Object.keys(errs).length) {
            e.preventDefault();
            setClientErrors(errs);
          } else {
            setClientErrors(null);
          }
        }}
      >
        <div>
          <label for="name">Name</label>
          <input id="name" name="name" type="text" value={values()?.name ?? ""} />
          <Show when={errors().name}><span>{errors().name}</span></Show>
        </div>
        <div>
          <label for="email">Email</label>
          <input id="email" name="email" type="email" value={values()?.email ?? ""} />
          <Show when={errors().email}><span>{errors().email}</span></Show>
        </div>
        <div>
          <label for="message">Message</label>
          <textarea id="message" name="message" value={values()?.message ?? ""} />
          <Show when={errors().message}><span>{errors().message}</span></Show>
        </div>
        <button type="submit">Send</button>
      </form>
    </>
  );
}
