export type Values = { name: string; email: string; message: string };
export type Errors = { name?: string; email?: string; message?: string };
export type Result = { values: Values; errors: Errors; ok: boolean };

export function validate(v: Values): Errors {
  const e: Errors = {};
  if (!v.name) e.name = "Name is required.";
  if (!v.email) e.email = "Email is required.";
  else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.email)) e.email = "Enter a valid email address.";
  if (v.message.length < 20) e.message = "Message must be at least 20 characters.";
  return e;
}

export function read(form: FormData): Values {
  const g = (k: string) => String(form.get(k) ?? "").trim();
  return { name: g("name"), email: g("email"), message: g("message") };
}

export function check(form: FormData): Result {
  const values = read(form);
  const errors = validate(values);
  return { values, errors, ok: Object.keys(errors).length === 0 };
}
