import { check, type Errors, type Result } from "~/lib/contact";
import { loadContact, submitContact } from "~/lib/data";

export const route = { preload: () => loadContact() };

export default function Contact() {
  const initial = createAsync(() => loadContact());
  const [result, setResult] = createSignal<Result | null | undefined>(undefined);
  const current = () => (result() === undefined ? initial() : result()) ?? null;
  const errors = (): Errors => current()?.errors ?? {};
  const values = () => current()?.values;

  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={current()?.ok}>
        <p>Thanks, {current()!.values.name}! Your message has been sent.</p>
